// Some portions generated by Claude
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

// The Graph page: a React island (scripts/graph-explorer/graph-explorer.mjs, an ES module built by Vite) that mounts
// into the lit-html outlet through the same route contract as every other page.

/** A document whose <script> elements load instantly, recording what the loader appended. */
function fakeDocument(appended) {
    const head = { appendChild(script) { appended.push(script); if (script.onload) { script.onload(); } } };
    return {
        head,
        body: head,
        readyState: 'complete',
        addEventListener() {},
        getElementById() { return null; },
        querySelector(selector) {
            const source = selector.match(/^script\[src="(.*)"\]$/);
            return source && appended.find((script) => script.src === source[1]) || null;
        },
        createElement(name) {
            assert.equal(name, 'script');
            const attributes = {};
            return {
                async: true,
                onload: null,
                onerror: null,
                parentNode: head,
                setAttribute(key, value) { attributes[key] = value; },
                getAttribute(key) { return key in attributes ? attributes[key] : null; }
            };
        }
    };
}

function loadWorkbench() {
    const appended = [];
    const window = { document: fakeDocument(appended), location: { href: 'https://example.test/wb/repositories/r/graph' } };
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout,
        clearTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        const absolutePath = path.join(scripts, filename);
        vm.runInContext(fs.readFileSync(absolutePath, 'utf8'), context, { filename: absolutePath });
    }
    window.workbench = context.workbench;
    return { workbench: context.workbench, window, appended };
}

function fakeRuntime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

function templateText(template) {
    if (Array.isArray(template)) {
        return template.map(templateText).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => result + fragment
            + (index < template.values.length ? templateText(template.values[index]) : ''), '');
    }
    return template === null || template === undefined || typeof template === 'object' ? '' : String(template);
}

function emptyModel(viewId) {
    return { viewId, vars: [], rows: [], rowStart: 0, rowCount: 0, rowTopSpacer: 0, rowBottomSpacer: 0,
        rowStore: null, namespaceMap: {}, links: [], metadata: {}, pickerRows: [], pickerStart: 0, pickerPageSize: 50 };
}

test('the graph route is registered, router-ready and loads only the explorer module', () => {
    const { workbench } = loadWorkbench();
    const route = workbench.routes.get('graph');
    assert.ok(route, 'graph route registered');
    assert.equal(route.viewId, 'graph');
    assert.equal(workbench.routes.isRouterReady('graph'), true);
    assert.deepEqual(Array.from(route.scripts(emptyModel('graph'))), ['graph-explorer/graph-explorer.mjs']);
});

test('mounting the graph route hands the outlet and the route context to the explorer and disposes it once', async () => {
    const { workbench } = loadWorkbench();
    const calls = [];
    let cleanups = 0;
    workbench.graphExplorer = {
        mount(outlet, ctx) {
            calls.push({ outlet, ctx });
            return () => { cleanups += 1; };
        }
    };
    workbench.views.renderOutlet = () => {};
    workbench.views.bindRowWindows = () => Promise.resolve(() => {});
    workbench.views.releasePage = () => {};
    const outlet = { id: 'workbench-outlet' };
    const ctx = { outlet, model: emptyModel('graph'), context: { basePath: '/wb', repositoryId: 'r' }, runtime: fakeRuntime(),
        url: 'https://example.test/wb/repositories/r/graph' };

    const instance = workbench.routes.get('graph').mount(ctx);
    await instance.ready;

    assert.equal(calls.length, 1);
    assert.equal(calls[0].outlet, outlet);
    assert.equal(calls[0].ctx, ctx, 'the route context is the second argument');
    instance.dispose('navigate');
    instance.dispose('navigate');
    assert.equal(cleanups, 1);
});

test('route scripts ending in .mjs are loaded as ES modules', async () => {
    const { workbench, appended } = loadWorkbench();

    await workbench.app.loadScripts(['graph-explorer/graph-explorer.mjs', 'explore.js']);

    assert.equal(appended.length, 2);
    assert.equal(appended[0].src, '/scripts/graph-explorer/graph-explorer.mjs');
    assert.equal(appended[0].type, 'module');
    assert.equal(appended[1].src, '/scripts/explore.js');
    assert.notEqual(appended[1].type, 'module');
    await workbench.app.loadScripts(['graph-explorer/graph-explorer.mjs']);
    assert.equal(appended.length, 2, 'a loaded module is not appended twice');
});

test('the graph page has a title, a description, a landing slot and a repository-scoped switch target', () => {
    const { workbench } = loadWorkbench();
    assert.equal(workbench.views.documentTitle('graph', 'r'), 'Graph · r — RDF4J Workbench');
    assert.equal(workbench.views.repositorySwitchTarget('/wb', 'graph', 'r'), '/wb/repositories/r/graph');
    const mount = {};
    workbench.views.render(mount, emptyModel('graph'), { basePath: '/wb', repositoryId: 'r', workbench: {} }, fakeRuntime());
    const text = templateText(mount.template);
    assert.match(text, /data-graph-explorer-mount/);
    assert.match(text, /class="graph-explorer-mount"/);
    assert.doesNotMatch(text, /Unsupported Workbench view/);
    assert.match(text, /interactive graph/i);
});

test('the repositories table offers a Graph link only when the policy shows the page', () => {
    const { workbench } = loadWorkbench();
    const row = (menuItems) => {
        const mount = {};
        const model = emptyModel('repositories');
        model.vars = ['id', 'description', 'location', 'readable', 'writeable'];
        model.rows = [['r', 'A repo', 'http://x', 'true', 'true']];
        model.rowCount = 1;
        // The Info model's policy-filtered menu: pages missing from it are hidden by the deployment policy.
        const workbenchInfo = { menuItems: menuItems.map((id) => ({ id, label: id, 'menu-group-id': 'explore' })) };
        workbench.views.render(mount, model, { basePath: '/wb', repositoryId: 'NONE', workbench: workbenchInfo },
            fakeRuntime());
        return templateText(mount.template);
    };
    assert.match(row(['query', 'explore', 'graph', 'summary']), /repositories\/r\/graph/);
    assert.doesNotMatch(row(['query', 'explore', 'summary']), /repositories\/r\/graph/);
});

test('the Graph menu item is unavailable, like Explore, until a readable repository is selected', () => {
    const { workbench } = loadWorkbench();
    const navigationLinks = (repositoryId, readable) => {
        const menuItems = ['query', 'explore', 'graph', 'repositories']
            .map((id) => ({ id, label: id, 'menu-group-id': id === 'repositories' ? 'repositories' : 'explore' }));
        // The Info model of /repositories/NONE/info says readable=false and writeable=false.
        const info = { menuItems, readable: String(readable), writeable: String(readable) };
        const template = workbench.views.pageTemplate(emptyModel('repositories'),
            { basePath: '/wb', repositoryId, workbench: info }, fakeRuntime());
        return templateText(template).match(/data-workbench-nav-href=[^\s>]+/g) || [];
    };

    const none = navigationLinks('NONE', false);
    assert.ok(!none.some((link) => link.endsWith('/explore')), 'Explore is disabled: ' + none.join(', '));
    assert.ok(!none.some((link) => link.endsWith('/graph')), 'Graph is disabled: ' + none.join(', '));
    assert.ok(none.some((link) => link.endsWith('/NONE/repositories')), 'Repositories stays available');

    const selected = navigationLinks('r', true);
    assert.ok(selected.some((link) => link === 'data-workbench-nav-href=/wb/repositories/r/graph'), selected.join(', '));
});
